import { completeRequest } from './completion.js';
import { elicitResult } from './elicitation.js';
import { initializedNotification, initializeRequest } from './initialize.js';
import { setLevelRequest } from './logging.js';
import { getPromptRequest, listPromptsRequest } from './prompt.js';
import { listResourcesRequest, listResourceTemplatesRequest, readResourceRequest, subscribeRequest, unsubscribeRequest } from './resource.js';
import { listRootsResult, rootsListChangedNotification } from './root.js';
import { cancelledNotification, errorResponse, pingRequest, progressNotification, response, result } from './rpc.js';
import { createMessageResult } from './sampling.js';
import { callToolRequest, listToolsRequest } from './tool.js';
// Client messages from https://github.com/modelcontextprotocol/specification/blob/e19c2d5768c6b5f0c7372b9330a66d5a5cc22549/schema/schema.ts#L1066
export const clientRequest = {
    anyOf: [
        pingRequest,
        initializeRequest,
        completeRequest,
        setLevelRequest,
        getPromptRequest,
        listPromptsRequest,
        listResourcesRequest,
        listResourceTemplatesRequest,
        readResourceRequest,
        subscribeRequest,
        unsubscribeRequest,
        listToolsRequest,
        callToolRequest
    ]
};
export const clientNotification = {
    anyOf: [
        cancelledNotification,
        progressNotification,
        initializedNotification,
        rootsListChangedNotification
    ]
};
export const clientResult = {
    anyOf: [
        result,
        createMessageResult,
        listRootsResult,
        elicitResult
    ]
};
export const clientResponse = {
    anyOf: [
        errorResponse,
        {
            allOf: [
                response,
                {
                    type: 'object',
                    properties: {
                        result: clientResult
                    },
                    required: [
                        'result'
                    ]
                }
            ]
        }
    ]
};
// Generic messages
/**
 * Any MCP client message.
 */ export const clientMessage = {
    anyOf: [
        pingRequest,
        initializeRequest,
        completeRequest,
        setLevelRequest,
        getPromptRequest,
        listPromptsRequest,
        listResourcesRequest,
        listResourceTemplatesRequest,
        readResourceRequest,
        subscribeRequest,
        unsubscribeRequest,
        listToolsRequest,
        callToolRequest,
        clientNotification,
        clientResponse
    ]
};
